    from collections import Counter

    # 1. Find background (most frequent color)
    colors = Counter()
    for row in grid:
        for val in row:
            colors[val] += 1
    background = max(colors, key=colors.get)

    # 2. Get connected components for each color
    def get_components(color):
        visited = set()
        comps = []
        for r in range(len(grid)):
            for c in range(len(grid[0])):
                if grid[r][c] == color and (r,c) not in visited:
                    comp = []
                    stack = [(r,c)]
                    visited.add((r,c))
                    comp.append((r,c))
                    while stack:
                        cr, cc = stack.pop()
                        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                            nr, nc = cr+dr, cc+dc
                            if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                                if grid[nr][nc] == color and (nr,nc) not in visited:
                                    visited.add((nr,nc))
                                    comp.append((nr,nc))
                                    stack.append((nr,nc))
                    comps.append(comp)
        return comps

    # 3. Find target color: color with exactly 2 components, pick smallest color value
    target_color = None
    for color in sorted(colors.keys()):
        if color != background:
            comps = get_components(color)
            if len(comps) == 2:
                target_color = color
                break

    # 4. Get all components of target color
    if target_color is None:
        for color in colors:
            if color != background:
                target_color = color
                break

    all_comps = get_components(target_color)

    # 5. Pick the EARLIEST (top-leftmost) component by position
    all_comps.sort(key=lambda c: (min(x[0] for x in c), min(x[1] for x in c)))
    selected_comp = all_comps[0] if all_comps else []

    # 6. Compute Bounding Box of selected component
    rows = [c[0] for c in selected_comp]
    cols = [c[1] for c in selected_comp]
    if not rows:
        return [[background] * 1 for _ in range(1)]
    min_r, max_r = min(rows), max(rows)
    min_c, max_c = min(cols), max(cols)

    # 7. Extract subgrid, replace non-background with target color
    result = []
    for r in range(max_r - min_r + 1):
        row_vals = []
        for c in range(max_c - min_c + 1):
            val = grid[min_r + r][min_c + c]
            if val == target_color:
                row_vals.append(target_color)
            else:
                row_vals.append(background)
        result.append(row_vals)

    return result
